const data = $input.all().map(item => item.json);

// Total loans
const totalLoans = data.length;

// Bad loans (Charged Off)
const badLoans = data.filter(d => d.loan_condition === "BAD LOAN").length;
const badLoanPct = totalLoans > 0 ? (badLoans / totalLoans) * 100 : 0;

// High-risk grades
const highRiskLoans = data.filter(d => ['D','E','F'].includes(d.grade)).length;

// Avg interest rate by grade
const interestByGrade = {};
const countByGrade = {};

data.forEach(d => {
  const g = d.grade;

  // Convert "13.56%" → 13.56
  const rate = parseFloat((d.interest_rate || "").toString().replace('%','')) || 0;

  if (!interestByGrade[g]) {
    interestByGrade[g] = 0;
    countByGrade[g] = 0;
  }

  interestByGrade[g] += rate;
  countByGrade[g]++;
});

// Final average
for (let g in interestByGrade) {
  interestByGrade[g] = (interestByGrade[g] / countByGrade[g]).toFixed(2);
}

// Region-wise defaults
const regionStats = {};

data.forEach(d => {
  const r = d.region;

  if (!regionStats[r]) {
    regionStats[r] = { total: 0, bad: 0 };
  }

  regionStats[r].total++;

  if (d.loan_condition === "BAD LOAN") {
    regionStats[r].bad++;
  }
});

const regionDefaultPct = {};

for (let r in regionStats) {
  regionDefaultPct[r] = regionStats[r].total > 0
    ? ((regionStats[r].bad / regionStats[r].total) * 100).toFixed(2)
    : "0.00";
}

// Final output
return [{
  json: {
    totalLoans,
    badLoanPct: badLoanPct.toFixed(2),
    highRiskLoans,
    interestByGrade,
    regionDefaultPct
  }
}];
